import{_ as i,o as a,c as t,a2 as l}from"./chunks/framework.BXzK3EA4.js";const o="/assets/Screenshot%202024-12-17%20at%203.38.04%E2%80%AFPM.DBgmYbJR.png",r="/assets/Screenshot%202024-12-17%20at%203.39.35%E2%80%AFPM.DU9zL0MD.png",n="/assets/Screenshot%202024-12-17%20at%204.31.16%E2%80%AFPM.opJ6MOY6.png",s="/assets/Screenshot%202024-12-17%20at%203.41.35%E2%80%AFPM.fewWJfbZ.png",u="/assets/Screenshot%202024-12-17%20at%204.10.01%E2%80%AFPM.BxRUm2Ai.png",d="/assets/Screenshot%202024-12-17%20at%203.42.54%E2%80%AFPM.D3N-5oSc.png",c="/assets/Screenshot%202024-12-17%20at%203.47.00%E2%80%AFPM.QPM9FNVe.png",p="/assets/Screenshot%202024-12-17%20at%203.52.43%E2%80%AFPM.BK3hS-ZY.png",S=JSON.parse('{"title":"ChartInk","description":"","frontmatter":{},"headers":[],"relativePath":"trading-platform/chartink.md","filePath":"trading-platform/chartink.md"}'),h={name:"trading-platform/chartink.md"};function g(m,e,y,q,f,b){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="chartink" tabindex="-1">ChartInk <a class="header-anchor" href="#chartink" aria-label="Permalink to &quot;ChartInk&quot;">​</a></h1><p>Tradeboard supports integration with Chartink for automated trading based on scanner alerts. This integration allows you to:</p><ul><li>Create and manage trading strategies</li><li>Configure symbols with quantities and product types</li><li>Currently Supports only NSE and BSE Symbols</li><li>Handle intraday and positional strategies</li><li>Automate order placement based on Chartink alerts</li><li>Auto square-off positions for intraday strategies</li></ul><figure><img src="'+o+'" alt=""><figcaption></figcaption></figure><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><p>ChartInk Paid Account (Supports Webhook Features to send Alerts to Tradeboard)</p><p>Ngrok with Custom Domain Configuration (Provides Webhooks to Chartink/Tradingview) if hosted locally in Laptop/Desktop. </p><p>Configure the .env file with Custom Domain (you cannot run Chartink by default with localhost or 127.0.0.1:5000)</p><h3 id="order-processing-system" tabindex="-1">Order Processing System <a class="header-anchor" href="#order-processing-system" aria-label="Permalink to &quot;Order Processing System&quot;">​</a></h3><h4 id="queue-management" tabindex="-1">Queue Management <a class="header-anchor" href="#queue-management" aria-label="Permalink to &quot;Queue Management&quot;">​</a></h4><p>Tradeboard uses a dual-queue system to handle orders efficiently:</p><ol><li>Regular Order Queue (Entry Orders): <ul><li>Handles BUY and SHORT orders</li><li>Processes up to 10 orders per second</li><li>Orders are batched for maximum throughput</li><li>Example: 50 BUY orders complete in ~5 seconds</li></ul></li><li>Smart Order Queue (Exit Orders): <ul><li>Handles SELL and COVER orders</li><li>Maintains 1-second delay between orders</li><li>Higher priority than entry orders</li><li>Example: 50 SELL orders complete in ~50 seconds</li></ul></li><li>Multiple Strategy Handling: <ul><li>All strategies share the same queues</li><li>Exit orders always processed before entries</li><li>Rate limits maintained across strategies</li><li>Each strategy respects its trading hours</li></ul></li><li>Auto Square-off Processing: <ul><li>Uses smart order queue</li><li>1-second delay between position closures</li><li>Processes positions sequentially</li><li>Example: 20 positions take ~20 seconds to close</li></ul></li></ol><h3 id="setting-up-a-strategy" tabindex="-1">Setting Up a Strategy <a class="header-anchor" href="#setting-up-a-strategy" aria-label="Permalink to &quot;Setting Up a Strategy&quot;">​</a></h3><figure><img src="'+r+'" alt=""><figcaption></figcaption></figure><ol><li>Open <strong>Trading Platforms</strong> from the Tradeboard navigation menu (<code>/platforms</code>) and click the <strong>Chartink</strong> card, which takes you to <code>/chartink</code></li><li>Click &quot;New Strategy&quot; button</li><li>Fill in the strategy details: <ul><li>Name: A unique name for your strategy (will be prefixed with &#39;chartink_&#39;). Only letters, numbers, spaces, hyphens and underscores are accepted.</li><li>Type: Choose between Intraday or Positional</li><li>For Intraday strategies: <ul><li>Start Time: Trading start time (default: 09:15)</li><li>End Time: Trading end time (default: 15:00)</li><li>Square Off Time: Auto square-off time (default: 15:15)</li><li>The three times are validated as start time &lt; end time &lt; square off time. A strategy that breaks that order is rejected.</li></ul></li></ul></li></ol><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><h3 id="alert-name-keywords" tabindex="-1">Alert Name Keywords <a class="header-anchor" href="#alert-name-keywords" aria-label="Permalink to &quot;Alert Name Keywords&quot;">​</a></h3><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p>The alert name in Chartink MUST include one of these keywords (not case-sensitive):</p><ol><li><strong>BUY</strong> - For entering long positions <ul><li>Examples: <ul><li>&quot;BUY Alert&quot;</li><li>&quot;Alert for BUY 2024-12-13&quot;</li><li>&quot;Supertrend BUY Signal&quot;</li></ul></li></ul></li><li><strong>SELL</strong> - For exiting long positions or regular selling <ul><li>Examples: <ul><li>&quot;SELL Alert&quot;</li><li>&quot;Alert for SELL 2024-12-13&quot;</li><li>&quot;Supertrend SELL Signal&quot;</li></ul></li></ul></li><li><strong>SHORT</strong> - For entering short positions (selling first) <ul><li>Examples: <ul><li>&quot;SHORT Alert&quot;</li><li>&quot;Alert for SHORT 2024-12-13&quot;</li><li>&quot;Supertrend SHORT Signal&quot;</li></ul></li></ul></li><li><strong>COVER</strong> - For exiting short positions (buying to cover) <ul><li>Examples: <ul><li>&quot;COVER Alert&quot;</li><li>&quot;Alert for COVER 2024-12-13&quot;</li><li>&quot;Supertrend COVER Signal&quot;</li></ul></li></ul></li></ol><figure><img src="'+u+`" alt=""><figcaption></figcaption></figure><h4 id="keyword-rules" tabindex="-1">Keyword Rules <a class="header-anchor" href="#keyword-rules" aria-label="Permalink to &quot;Keyword Rules&quot;">​</a></h4><ul><li>Keywords can appear anywhere in the alert name</li><li>Keywords are not case-sensitive (buy/BUY/Buy all work)</li><li>Alert will fail if no valid keyword is found</li><li>Only one action will be taken even if multiple keywords are present</li></ul><h3 id="configuring-symbols" tabindex="-1">Configuring Symbols <a class="header-anchor" href="#configuring-symbols" aria-label="Permalink to &quot;Configuring Symbols&quot;">​</a></h3><p>After creating a strategy, you need to configure the symbols to trade:</p><ol><li><p>Click &quot;Configure Symbols&quot; on your strategy</p></li><li><p>Add symbols individually:</p><ul><li>Search and select Symbol (with exchange badge)</li><li>Select Exchange. Only NSE and BSE are accepted here.</li><li>Enter Quantity, in units and not lots</li><li>Select Product Type. Only MIS and CNC are accepted. NRML is not offered, because Chartink strategies are equity only.</li></ul></li><li><p>Or bulk add symbols using CSV format, one row per symbol as <code>ChartinkSymbol,Exchange,Quantity,Product</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RELIANCE,NSE,10,MIS</span></span>
<span class="line"><span>HDFCBANK,NSE,5,CNC</span></span>
<span class="line"><span>TATASTEEL,BSE,15,MIS</span></span></code></pre></div></li></ol><figure><img src="`+d+'" alt=""><figcaption></figcaption></figure><h3 id="setting-up-chartink-alert" tabindex="-1">Setting Up Chartink Alert <a class="header-anchor" href="#setting-up-chartink-alert" aria-label="Permalink to &quot;Setting Up Chartink Alert&quot;">​</a></h3><p><strong>Creating a Scanner</strong></p><ol><li>Goto <a href="https://chartink.com/scan_dashboard" target="_blank" rel="noreferrer">Chartink Scanner Dashboard</a></li><li>Click &quot;Create a new scanner&quot; button</li><li>Create the Scanner conditions and Press Save Scan</li><li>Enter an alert name that includes one of the action keywords</li></ol><figure><img src="'+c+'" alt=""><figcaption></figcaption></figure><p>Creating Alert</p><ol><li><p>Once the Scanner is Saved Click Create Alert</p></li><li><p>Find the &quot;Webhook url(optional)&quot; field</p></li><li><p>Copy and paste your strategy&#39;s webhook URL:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-tradeboard-domain/chartink/webhook/&lt;webhook-id&gt;</span></span></code></pre></div></li><li><p>Configure other alert settings as needed</p></li><li><p>Click &quot;Save alert&quot; button</p></li></ol><figure><img src="'+p+`" alt=""><figcaption></figcaption></figure><h3 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h3><ol><li>When your scanner conditions are met, Chartink sends an alert to your webhook URL</li><li>Tradeboard receives the alert and: <ul><li>Validates the webhook ID</li><li>Checks if strategy is active</li><li>Validates the alert name for action keyword</li><li>For intraday strategies, checks if within trading hours</li><li>Matches symbols from alert with your configured symbols</li><li>Places orders according to your configuration</li></ul></li></ol><h4 id="intraday-trading" tabindex="-1">Intraday Trading <a class="header-anchor" href="#intraday-trading" aria-label="Permalink to &quot;Intraday Trading&quot;">​</a></h4><p>For intraday strategies:</p><ul><li>Orders are only placed between Start Time and End Time</li><li>At Square Off Time, all open positions are automatically closed</li><li>Uses MIS product type for better leverage</li></ul><h4 id="positional-trading" tabindex="-1">Positional Trading <a class="header-anchor" href="#positional-trading" aria-label="Permalink to &quot;Positional Trading&quot;">​</a></h4><p>For positional strategies:</p><ul><li>Orders can be placed any time during market hours</li><li>No automatic square-off</li><li>Uses CNC product type for delivery trades</li></ul><h3 id="order-placement" tabindex="-1">Order Placement <a class="header-anchor" href="#order-placement" aria-label="Permalink to &quot;Order Placement&quot;">​</a></h3><p>When a Chartink alert is received:</p><ul><li><p>For entries (a BUY or SHORT keyword in the scan name), sent to <code>/api/v1/placeorder</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;apikey&quot;: &quot;your-api-key&quot;,</span></span>
<span class="line"><span>  &quot;strategy&quot;: &quot;Strategy Name&quot;,</span></span>
<span class="line"><span>  &quot;symbol&quot;: &quot;SYMBOL&quot;,</span></span>
<span class="line"><span>  &quot;exchange&quot;: &quot;NSE/BSE&quot;,</span></span>
<span class="line"><span>  &quot;action&quot;: &quot;BUY or SELL&quot;,</span></span>
<span class="line"><span>  &quot;product&quot;: &quot;MIS/CNC&quot;,</span></span>
<span class="line"><span>  &quot;pricetype&quot;: &quot;MARKET&quot;,</span></span>
<span class="line"><span>  &quot;quantity&quot;: &quot;configured-quantity&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Note that <code>action</code> is always <code>BUY</code> or <code>SELL</code> on the wire. SHORT becomes <code>SELL</code> and COVER becomes <code>BUY</code>; the SHORT and COVER keywords exist only to tell Tradeboard whether the alert is an entry or an exit.</p></li><li><p>For exits and for the scheduled square-off, sent to <code>/api/v1/placesmartorder</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;apikey&quot;: &quot;your-api-key&quot;,</span></span>
<span class="line"><span>  &quot;strategy&quot;: &quot;Strategy Name&quot;,</span></span>
<span class="line"><span>  &quot;symbol&quot;: &quot;SYMBOL&quot;,</span></span>
<span class="line"><span>  &quot;exchange&quot;: &quot;NSE/BSE&quot;,</span></span>
<span class="line"><span>  &quot;action&quot;: &quot;SELL&quot;,</span></span>
<span class="line"><span>  &quot;product&quot;: &quot;MIS&quot;,</span></span>
<span class="line"><span>  &quot;pricetype&quot;: &quot;MARKET&quot;,</span></span>
<span class="line"><span>  &quot;quantity&quot;: &quot;0&quot;,</span></span>
<span class="line"><span>  &quot;position_size&quot;: &quot;0&quot;,</span></span>
<span class="line"><span>  &quot;price&quot;: &quot;0&quot;,</span></span>
<span class="line"><span>  &quot;trigger_price&quot;: &quot;0&quot;,</span></span>
<span class="line"><span>  &quot;disclosed_quantity&quot;: &quot;0&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>With <code>position_size</code> set to <code>0</code>, Tradeboard looks up the live open position and flattens it, working out the direction itself. The <code>action</code> field in this payload is therefore ignored, and if the position is already flat no order reaches the broker.</p></li></ul><h3 id="strategy-management" tabindex="-1">Strategy Management <a class="header-anchor" href="#strategy-management" aria-label="Permalink to &quot;Strategy Management&quot;">​</a></h3><h4 id="activation-deactivation" tabindex="-1">Activation/Deactivation <a class="header-anchor" href="#activation-deactivation" aria-label="Permalink to &quot;Activation/Deactivation&quot;">​</a></h4><ul><li>Active strategies process incoming alerts</li><li>Inactive strategies ignore alerts</li><li>Toggle status from strategy view</li></ul><h4 id="symbol-management" tabindex="-1">Symbol Management <a class="header-anchor" href="#symbol-management" aria-label="Permalink to &quot;Symbol Management&quot;">​</a></h4><ul><li>Add/remove symbols any time</li><li>Update quantities as needed</li><li>View all configured symbols with exchange badges</li><li>Bulk import for multiple symbols</li><li>Delete confirmation for symbol removal</li></ul><h4 id="time-controls" tabindex="-1">Time Controls <a class="header-anchor" href="#time-controls" aria-label="Permalink to &quot;Time Controls&quot;">​</a></h4><p>For intraday strategies:</p><ul><li>Start Time: When to start accepting alerts</li><li>End Time: When to stop accepting alerts</li><li>Square Off Time: When to close all positions</li></ul><h3 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h3><ol><li>Use Chartink Custom Watchlists <ul><li>Create custom watchlists with only your trading symbols</li><li>Avoid scanning large portfolios like NIFTY500, NIFTY200</li><li>Helps manage positions efficiently</li><li>Reduces processing time for orders</li><li>Better control over trading universe</li></ul></li><li>Test your strategy with small quantities first <ul><li>Verify order placement</li><li>Check position management</li><li>Monitor square-off process</li><li>Validate webhook integration</li></ul></li><li>Use proper stop-losses in your Chartink scanner <ul><li>Implement risk management rules</li><li>Set appropriate price conditions</li><li>Add volume filters if needed</li></ul></li><li>Monitor the first few alerts <ul><li>Verify order execution</li><li>Check processing times</li><li>Validate symbol matching</li><li>Ensure proper position tracking</li></ul></li><li>Keep your webhook URL private <ul><li>Don&#39;t share webhook URLs</li><li>Regularly check for unauthorized alerts</li><li>Monitor strategy activity</li></ul></li><li>Include action keyword in scan name <ul><li>Use clear, consistent naming</li><li>Follow keyword rules strictly</li><li>Avoid multiple keywords</li></ul></li><li>For intraday strategies: <ul><li>Ensure orders are placed during trading hours</li><li>Monitor square-off at configured time</li><li>Plan for processing delays with large lists</li></ul></li><li>For large symbol lists: <ul><li>Entry orders process faster (10/sec)</li><li>Exit orders take longer (1/sec)</li><li>Plan strategy timing accordingly</li><li>Consider splitting into multiple strategies</li></ul></li></ol><h3 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h3><p>Tradeboard handles various error scenarios:</p><ul><li>Invalid webhook IDs</li><li>Missing action keywords in alert names</li><li>Inactive strategies</li><li>Outside trading hours</li><li>Symbol mismatches</li><li>Order placement failures</li></ul><p>All errors are logged and can be viewed in the API analyzer.</p><h3 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h3><ol><li>Only supports NSE and BSE exchanges</li><li>Intraday square-off is all-or-nothing</li><li>No partial position closures</li><li>No modification of existing orders</li><li>Market orders only</li><li>Alert name must contain valid action keyword</li></ol><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li>Each strategy has a unique webhook ID</li><li>API keys are required for order placement</li><li>Session validation for web interface</li><li>Secure storage of credentials</li><li>Rate limiting on the webhook endpoint, 100 requests per minute by default (<code>WEBHOOK_RATE_LIMIT</code>)</li><li>Confirmation dialogs for deletions</li></ul><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><ol><li>Check strategy status (active/inactive)</li><li>Verify trading hours for intraday</li><li>Confirm symbol configurations</li><li>Check alert name contains valid keyword</li><li>Check API analyzer for errors</li><li>Verify webhook URL in Chartink</li></ol><h3 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h3><p>For issues or questions:</p><ol><li>Check the logs in API analyzer</li><li>Review error messages</li><li>Contact support with: <ul><li>Strategy ID</li><li>Error details</li><li>Time of occurrence</li><li>Relevant logs</li><li>Alert name and webhook URL used</li></ul></li></ol>`,68)])])}const C=i(h,[["render",g]]);export{S as __pageData,C as default};
